style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.postimg.cc/ZRNfRytw/nazunawallpaper1correcoes.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Remove as cores sólidas do fundo */
  .container-main,
  .content,
  .profile-container,
  .section,
  .page-content,
  .game-home-page,
  #header,
  .footer,
  .theme-dark,
  .dark-theme,
  .container {
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
  }

  /* Esconde sobreposição escura que pode existir */
  .dark-overlay, .theme-dark::before {
    display: none !important;
  }
}
